-- Initializes vector extension, tables, and seeds embeddings.
-- Runs only on first DB initialization (when volume is empty).

-- pgvector extension
CREATE EXTENSION IF NOT EXISTS vector;

-- event_embeddings table
CREATE TABLE IF NOT EXISTS public.event_embeddings (
    id SERIAL PRIMARY KEY,
    event_date TEXT,
    holiday_info TEXT,
    category TEXT,
    about TEXT,
    food_customs TEXT,
    embedding vector(384)
);

-- product_embeddings table
CREATE TABLE IF NOT EXISTS public.product_embeddings (
    id SERIAL PRIMARY KEY,
    product_id INTEGER UNIQUE,
    farmer_id INTEGER,
    product_name VARCHAR(255),
    category VARCHAR(100),
    unit VARCHAR(50),
    price DECIMAL(10,2),
    quantity INTEGER,
    farmer_description TEXT,
    product_description TEXT,
    embedding vector(384)
);

-- IVFFlat index for cosine distance search
CREATE INDEX IF NOT EXISTS idx_product_embeddings_embedding
    ON product_embeddings USING ivfflat (embedding vector_cosine_ops) WITH (lists = 100);

