е насыщенный вкус мяса. INSERT INTO public.product_embeddings (id, product_id, farmer_id, product_name, category, unit, price, quantity, embedding, farmer_description, product_description) VALUES (1812, 38912, 15034, 'Сыр с тмином 5 месяца вызревания ', 'Сыры', 'шт', 15034.00, 0, '[0.039973192,-0.017202675,-0.015589795,-0.04341536,0.07246434,-0.01710113,0.04697058,0.0077108652,0.009234503,0.042881794,0.04362483,-0.027096031,0.11365799,-0.061145183,-0.02788724,0.005605656,0.03103412,-0.060405657,-0.04182939,-0.08421405,0.06476528,-0.023696799,-0.0068747164,0.046380512,0.0830767,0.0933293,-0.04183724,-0.021167142,0.048837595,-0.044024352,-0.033923663,-0.0228591,0.0040170164,-0.031182962,0.061080914,0.053413693,-0.062330857,-0.023045281,0.06920554,-0.06638571,-0.033417158,-0.00050121226,0.083009146,0.040411737,0.024858344,0.03180921,-0.051964406,0.018957933,-0.045648012,-0.044189185,-0.07026319,0.043464202,-0.0042211753,0.023135489,0.015835254,-0.060109347,-0.038217675,-0.048655987,-0.02788911,0.05478055,0.056473397,-0.01913274,0.068596385,0.010262216,0.06394357,0.05473036,0.069866784,-0.0006334481,-0.074647814,-0.047854476,-0.02577994,0.04641716,0.02527612,-0.029452171,0.013294081,-0.026240114,-0.0141498735,-0.04201431,0.05534265,-0.019199528,-0.076370105,-0.02562746,-0.042794917,-0.012146009,-0.04485057,0.059627168,0.008963991,-0.060975224,0.08608045,-0.040243223,0.05754958,0.015735785,-0.06202892,-0.028613599,-0.06378096,-0.032469437,-0.041911032,0.039763827,0.016568288,-0.03213301,0.072910026,-0.029082831,0.04077411,-0.082006976,0.011418439,0.062281877,0.03950748,-0.034383267,0.0313986,-0.036942486,-0.037039664,0.013420675,0.03164789,0.036958233,-0.013875049,-0.036031045,0.05967158,-0.07271606,0.09964253,-0.051257566,0.091767885,-0.063517295,-0.04219485,-0.12202978,-0.071242444,-0.044678316,0.04141392,-0.023654982,0.011168172,0.03642599,0.06930083,0.08676462,-0.021836428,0.031962942,0.04311222,0.052712787,-0.028389309,-0.026600016,0.03130446,-0.009916366,-0.032346