Без нагрева и контакта с металлом, бережным старинным методом в бочонке. Сохраняем все природные свойства!Спасибо, что выбрали нас и доверились!INSERT INTO public.product_embeddings (id, product_id, farmer_id, product_name, category, unit, price, quantity, embedding, farmer_description, product_description) VALUES (1520, 26792, 10619, 'Варенье малина', 'Сладости', 'шт', 10619.00, 0, '[0.011199942,-0.017447669,-0.03191144,-0.03178178,0.05875232,0.0034558314,0.022952657,-0.020583535,0.020407058,0.044145864,0.066260874,-0.022266814,0.040314924,-0.06579625,-0.041998193,0.028470693,0.04826204,-0.025693757,-0.04731981,-0.073728055,0.017940579,-0.02084913,0.017438803,0.026584962,0.0790427,0.09320428,-0.05852457,0.025543999,0.0375956,-0.05146099,-0.013364779,-0.03333464,0.064779155,-0.033100188,0.059890248,0.028137362,-0.07329293,-0.039862536,0.054822106,-0.03702726,-0.078555584,0.011199727,0.051753506,0.060849138,0.027580433,0.046367697,-0.047806025,0.02514722,-0.055085286,-0.037737563,-0.074797764,0.047277108,-0.033177275,0.014242642,0.020088166,-0.040156916,-0.089313574,-0.06902633,-0.025837561,0.040195987,0.041242503,-0.018702893,0.016534006,-0.006188037,0.06292682,0.055568878,0.07767943,0.02074816,-0.07238903,-0.03355672,0.009034529,0.06543524,0.010813045,-0.03789355,0.023248391,-0.0016140693,-0.009927296,-0.065911524,0.048252128,-0.014411902,-0.047425285,0.0013983682,-0.012272771,0.048218362,-0.052600715,0.06432515,0.030894471,-0.07561113,0.06977906,-0.050718922,0.037104413,0.02171054,-0.032051712,-0.05796221,-0.060182855,-0.059915397,-0.060534537,0.04306989,0.02830259,-0.02509717,0.047055963,0.003068197,-0.011791752,-0.12297878,0.0036918928,0.08728008,0.0650114,-0.054303154,0.034170065,-0.06755225,-0.04967031,0.047721915,0.053869817,0.047330264,-0.052549805,0.0061098714,0.025961433,-0.10118578,0.08432308,-0.08130177,0.06292221,-0.044015907,-0.010332279,-0.051752117,-0.075500496,-0.027645832,0.019040281,-0.032790463,0.017974121,0.009084302,0.020596677,0.047875322,-0.