дете потрясены. Если Вы хотите купить белую рыбу, то стоит попробовать стейки нельмы холодного копчения.INSERT INTO public.product_embeddings (id, product_id, farmer_id, product_name, category, unit, price, quantity, embedding, farmer_description, product_description) VALUES (2209, 149771, 22093, 'Набор из фруктовых чипсов Snack mini 80 гр', 'Сладости', 'шт', 22093.00, 0, '[0.00043605472,0.0048110406,-0.026757114,-0.07085825,0.072873,-0.031204833,-0.0076230676,-0.020133454,0.052649405,0.019402927,0.03292415,-0.040202823,0.0815616,-0.026119389,-0.033871345,0.0005294838,0.012493274,-0.05148101,-0.01273331,-0.06799606,0.017915674,0.0036518148,-0.021557938,0.014358761,0.041986194,0.059798673,-0.08357841,-0.045352705,0.039095517,-0.086847596,-0.059783407,-0.0096181,0.035243537,-0.033795718,0.05543193,0.018178973,-0.047516994,-0.038257774,0.0788408,-0.08489442,-0.02328973,0.015254455,0.05079819,0.043644562,0.04197647,0.056584556,-0.07145062,0.053465586,-0.043299496,-0.042395514,-0.049589083,0.04493531,0.0056726635,0.049145475,-0.016262852,-0.026336957,-0.053718623,-0.05496176,-0.014332544,0.048728716,0.017008916,-0.013715555,0.03281004,0.024572955,0.048549507,0.07368895,0.05988278,0.018544044,-0.06159348,-0.062217258,-0.0039785947,0.040586397,0.020095972,-0.03363916,0.038548786,0.020627461,-0.013093593,-0.03656079,0.08555281,-0.023060415,-0.09290243,-0.016449831,-0.03187469,0.022125455,-0.032798536,0.028361652,0.0764663,-0.04864865,0.10691704,-0.047505185,0.07620488,-0.028281346,-0.04957673,-0.08210148,-0.1143416,-0.042722244,-0.046273928,0.042159226,0.02873656,-0.06428968,0.08635323,-0.029210543,0.018434605,-0.10038835,0.0014070892,0.0716163,0.023123106,-0.05233037,0.045379125,-0.052478623,-0.037263814,0.046537723,0.05657931,0.024578268,-0.02178351,-0.023194393,0.014822516,-0.103753276,0.08219463,-0.042039827,0.06761018,-0.048428323,-0.041218378,-0.065701954,-0.054228626,-0.050488207,0.023377217,0.0017685163,-0.035197977,0.047647335,0.026080644,0.06527473,0.020045469,0.