опченного филе омуля в масле.INSERT INTO public.product_embeddings (id, product_id, farmer_id, product_name, category, unit, price, quantity, embedding, farmer_description, product_description) VALUES (3144, 149774, 22093, 'Пастила без сахара «Лимон-имбирь» 30 гр.', 'Сладости', 'шт', 22093.00, 0, '[-0.01218223,0.003010387,-0.018417977,-0.055269092,0.071677975,-0.030169152,0.00429052,-0.035843648,0.05866444,0.025256008,0.020774318,-0.023298055,0.06104084,-0.03758928,-0.024291618,0.019549513,0.008017632,-0.046231177,-0.017502451,-0.06174651,-0.0005565417,-0.004159512,-0.01041994,0.01332183,0.041568577,0.061493378,-0.07122649,-0.04071554,0.065952435,-0.084171526,-0.057612974,-0.02913613,0.04152783,-0.043090053,0.058237348,0.0034773008,-0.0487508,-0.024477234,0.09139659,-0.07245605,-0.028181849,-0.00056518405,0.031756975,0.06591551,0.05501219,0.028505458,-0.075335376,0.042167302,-0.030451192,-0.028389731,-0.06361805,0.048989438,-0.0032725057,0.029328909,-0.018232886,-0.027040709,-0.059762374,-0.06821847,-0.026741141,0.052583292,0.028306236,-0.00950013,0.026447935,0.024087884,0.021900699,0.07695836,0.06978413,0.029361777,-0.045852605,-0.06244489,0.0017250269,0.023821272,0.030744804,-0.044532355,0.028281229,0.014205034,-0.0037953146,-0.05997692,0.06496898,-0.028196555,-0.08155831,-0.025103392,-0.017976705,0.004007815,-0.037903078,0.009031197,0.06692169,-0.060009114,0.10636746,-0.041690428,0.0699951,-0.01829962,-0.039247997,-0.10810908,-0.109006666,-0.07141115,-0.050940506,0.042150993,0.033014275,-0.070557006,0.070418775,-0.017352287,0.022985412,-0.121822566,-2.8361524e-06,0.09422033,0.04335812,-0.05855619,0.042909473,-0.050245814,-0.033186484,0.0453047,0.07113946,0.02786547,-0.027727865,-0.030420389,0.00593205,-0.0887875,0.079872504,-0.03983792,0.07058881,-0.06748581,-0.042128406,-0.05316357,-0.058319762,-0.023693977,0.015241907,0.000632599,-0.010928378,0.0832568,0.011550005,0.031662785,0.009067861,0.011586292,0.020422336,0.08547569,-0.046621695,0.0025141377,0.034432303,