обязательно попробуйте нарезку филе муксуна холодного копчения.INSERT INTO public.product_embeddings (id, product_id, farmer_id, product_name, category, unit, price, quantity, embedding, farmer_description, product_description) VALUES (2493, 162508, 27572, 'Яйцо куриное', 'Яйца и молочные продукты', 'шт', 27572.00, 0, '[0.015607165,0.004889507,-0.005509816,-0.038765386,0.043843642,0.0016146691,0.023173444,-0.0038232654,0.042078815,-0.0038166346,0.029553128,0.01633476,0.009820441,-0.07387115,-0.046722434,0.003841605,0.04023992,-0.021765733,-0.027565688,-0.08853464,-0.001653887,-0.021900333,0.019710321,0.038135726,0.091924205,0.076854795,-0.06458051,-0.0047048265,0.04740925,-0.063497595,-0.071618706,-0.04158674,0.021802733,-0.062746026,0.043323264,0.04037662,-0.022548897,-0.064610936,0.047446825,-0.065569095,-0.07181407,-0.0032158454,0.04601435,0.05751659,0.011131064,0.06519717,-0.07120535,0.036119338,-0.026550476,0.007384926,-0.089527026,0.06862583,-0.011601243,-0.008781902,0.02553937,-0.036401547,-0.04081062,-0.075295955,-0.024273789,0.059907455,0.0406683,-0.024007346,0.040250644,0.017686097,0.053565804,0.036616646,0.06661219,0.032322366,-0.033852313,-0.06849837,-0.037595496,0.009436902,0.033804476,0.001883713,-0.012911223,-0.01742503,0.021176541,-0.03843773,0.069131084,0.005435873,-0.10244122,-0.05060067,-0.0825895,0.04626983,-0.071249664,0.046092533,0.02750119,-0.051152635,0.06534925,-0.060808226,0.008554641,0.0036278556,-0.0048787077,-0.060126916,-0.06909955,-0.070460804,-0.08144907,0.05440186,0.029271474,-0.03351973,0.07400198,-0.06256288,0.030248353,-0.087616816,-0.004969524,0.06338416,0.047550865,-0.049548667,0.070043914,-0.056679975,-0.025009355,0.0139679825,0.06860885,0.025650222,-0.08337201,-0.054471742,0.025903808,-0.08657455,0.06089641,-0.063654765,0.047760535,-0.062833175,-0.039280776,-0.10254653,-0.039935097,-0.05501592,0.060120456,-0.026143255,0.038452175,0.06499293,0.051746763,0.067774825,0.015468606,0.030609544,0.068338506,0.036460947,-0.036188643,-