ни свежесть, ни качество, ни вкус нашей продукции.', 'Под этим названием он больше известен в Якутии, где по вкусовым качествам чиру отдают второе место, после нельмы. Мясо жирное, но к удивлению не калорийное. Купите этот деликатес и насладитесь удивительным вкусом филе чира холодного копчения.INSERT INTO public.product_embeddings (id, product_id, farmer_id, product_name, category, unit, price, quantity, embedding, farmer_description, product_description) VALUES (742, 138539, 27149, 'Стейк из осетра', 'Рыба и морепродукты', 'шт', 27149.00, 0, '[0.01815955,0.012107126,-0.049910538,-0.04435314,0.121581875,-0.0065755513,0.042477872,-0.003567807,0.029534498,0.008823367,0.0019287325,-0.049801826,0.041589078,-0.041864153,0.0008642606,0.03158176,0.06542023,-0.01994267,-0.09007356,-0.055606253,0.05998399,-0.019461306,-0.0073790397,0.043624956,0.059599727,0.05700681,-0.029764181,0.01256141,0.07455401,-0.059869617,-0.007746046,-0.010174196,0.04146149,-0.07200067,0.02321768,0.05418196,-0.048232578,-0.06682042,0.07729326,-0.018472396,-0.04670261,0.02157105,0.04846019,0.069725044,-0.014324752,0.039713494,-0.064477846,0.05001315,-0.029763633,-0.03987622,-0.07176516,0.084990405,0.00034149678,0.04023788,-0.004736774,-0.034507778,-0.009310264,-0.054223996,-0.0151320705,0.060878262,-0.033251923,0.014482768,-0.012298462,0.023608146,0.022623729,0.060872663,0.06797396,0.022562956,-0.070143454,-0.02592279,-0.028898034,0.029500604,-0.010557389,-0.009362685,0.006618358,-0.007082264,0.042804252,-0.04636849,0.070245795,-0.030340407,-0.08515732,-0.042149194,-0.061055,0.07671918,-0.06392026,0.083644845,0.041768096,-0.08710203,0.1010993,-0.039146993,0.037863582,0.022742067,-0.020633597,-0.082783535,-0.09115165,-0.054764416,-0.06414105,0.04408331,0.045435946,-0.038069718,0.039588716,-0.023984129,0.018389693,-0.113427475,0.009268202,0.031114316,0.09290872,-0.07941843,0.07032738,-0.05889827,-0.062146228,0.022568608,0.037594743,0.027081123,-0.062047645,-0.025843589,-0.0016824931,-0.056855105,0.04