ьно купите свежемороженую непотрошеную тушку муксуна.INSERT INTO public.product_embeddings (id, product_id, farmer_id, product_name, category, unit, price, quantity, embedding, farmer_description, product_description) VALUES (2456, 123867, 25860, 'Ломтики филе муксуна подкопченые в масле', 'Рыба и морепродукты', 'шт', 25860.00, 0, '[0.05201253,0.004758359,-0.081807025,-0.038781233,0.0720783,0.0068448363,0.03620134,0.011082559,0.043838527,0.008896581,0.024815131,-0.011789095,0.06472603,-0.08358135,-0.026507167,0.05039781,0.02495867,-0.071456976,-0.04224433,-0.044158593,0.04819665,-0.014593721,-0.007933557,0.028242273,0.051378258,0.07955298,-0.05548823,0.008785976,0.038949564,-0.11243066,-0.026696762,-0.013120995,0.044159107,-0.058144238,0.07145277,0.01711249,-0.05650829,-0.020381287,0.058146667,-0.02738743,-0.04658881,0.0030174037,0.049813163,0.09698555,0.04162327,0.04841126,-0.02327096,0.04974418,-0.021144524,-0.046354268,-0.07030339,0.07522781,-0.0046707224,-0.0014339171,-0.04174005,-0.014408409,-0.07494916,-0.062731214,-0.08545487,0.07339286,0.028686889,-0.03187175,0.02619103,-0.012040415,0.049505465,0.038002737,0.063623965,0.022631167,-0.06735168,-0.09051909,-0.03606146,0.02142968,0.015301344,-0.023865614,0.021525897,0.030750172,0.0455994,-0.035758384,0.08517629,0.018755373,-0.06967077,0.009913871,-0.05545996,-0.0045131794,-0.04917843,0.06355561,0.033686776,-0.075940214,0.09045493,-0.027204324,0.062023375,0.010220424,-0.025366886,-0.07122114,-0.07829285,-0.07338568,-0.06896549,0.012186415,0.01446935,-0.067430735,0.06123782,-0.02743729,0.005766122,-0.10001865,0.0067220246,0.0521809,0.07642619,-0.06799132,0.023569874,-0.086747706,-0.033266027,0.021247828,0.099810146,0.053806324,-0.068736404,-0.059117164,0.010002319,-0.046497807,0.07915824,-0.06222433,0.060341604,-0.06376866,-0.03094428,-0.05441477,-0.058266528,-0.05122414,0.012070048,0.0061119706,0.045754924,-0.019875197,0.032326855,0.03611625,0.016560314,0.039784234,0.009442387,0.069835074,-0.052337114,-0.0077692